boxes=['R','B','G']

def swap_contents(state,p,q):
    s={k:list(v) for k,v in state.items()}
    s[p],s[q]=s[q],s[p]
    return s

def swap_labels(labels,p,q):
    l=labels.copy()
    # labels: mapping from box->label
    l[p],l[q]=l[q],l[p]
    return l

def find_box(state,obj):
    for b,items in state.items():
        if obj in items:return b
    raise ValueError

def move_pair_into(state,a,b,target):
    # remove from their boxes and add to target
    ns={k:list(v) for k,v in state.items()}
    # remove all occurrences unique assumption
    for bo in boxes:
        ns[bo]=[x for x in ns[bo] if x"'!=a and x!=b]
    # add one each
    ns[target].append(a)
    if b!=a: ns[target].append(b)
    return ns

def move_single_into(state,obj,target):
    ns={k:list(v) for k,v in state.items()}
    src=find_box(ns,obj)
    ns[src].remove(obj)
    ns[target].append(obj)
    return ns

