        # ensure unique exists
        if 'C' not in sum(st3.values(),[]):
            continue
        # step4 swap labels B/G
        lab4=swap_labels(labels,'B','G')
        # step5 move B into box currently labeled R
        # find physical box with label R
        t5=[b for b,l in lab4.items() if l=='R'][0]
        st5=move_single_into(st3,'B',t5)
        for p6 in P2:
            st6=swap_contents(st5,*p6)
            # evaluate final by labels: label->content list
            by_label={}
            for b,ls in lab4.items():
                by_label[ls]=[x for x in st6[b]]
            # check single each
            if all(len(by_label[l])==1 for l in ['R','B','G']):
                print('init',init,'t1',t1,'p2',p2,'p6',p6,'final',by_label)
                raise SystemExit
print('done')
